return db.Transaction(func(tx *gorm.DB) error {
    var lock LockRecord
    err := tx.Clauses(clause.Locking{Strength: "UPDATE"}).
        Where("lockable = ?", key).First(&lock).Error
    switch {
    case errors.Is(err, gorm.ErrRecordNotFound):
        return tx.Create(&LockRecord{Lockable: key, Owner: sessionID,
            AcquiredAt: time.Now()}).Error
    case err != nil:
        return err
    case lock.Owner != sessionID:
        return ErrLocked
    }
    return nil
})
